    /// <summary>
    /// Method to enable/disable Custom buttons on the form
    /// </summary>
    /// <param name="sender">Get Table buffer</param>
    /// <param name="e"> Get form data source args</param>
    [
        FormDataSourceEventHandler(formDataSourceStr(TAMRebateDeal, TAMRebateDeal), FormDataSourceEventType::Activated),
        SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")
    ]
    public static void TAMRebateDeal_OnActivated(FormDataSource sender, FormDataSourceEventArgs e)
    {
        TAMRebateDeal rebateDeal;
        
        rebateDeal = sender.cursor();

        if(rebateDeal.METExcludeForPaymentItems == NoYes::Yes)
        {
            Integer excludeforPaymenteButton =   sender.formRun().controlId(formControlStr(TAMRebateDeal, METRebateExcludeForPayment));
            sender.formRun().control(excludeforPaymenteButton).visible(true);
        }
        else
        {
            Integer excludeforPaymenteButton =   sender.formRun().controlId(formControlStr(TAMRebateDeal, METRebateExcludeForPayment));
            sender.formRun().control(excludeforPaymenteButton).visible(false);
        }

        //NS - Created for the FSD - CB201, Rebates Extension - Undertake Build -  External Data Sources
        if (rebateDeal.RebateActive == NoYes::No)
        {
            sender.formRun().design().controlName(formControlStr(TAMRebateDeal, METUseExternalSellData)).enabled(true);
        }
        else
        {
            sender.formRun().design().controlName(formControlStr(TAMRebateDeal, METUseExternalSellData)).enabled(false);

        }

        if(rebateDeal.METVolumetricTierDeal == NoYes::Yes)
        {
            FormControl tierLineType = sender.formRun().design().controlName(formControlStr(TAMRebateDeal, TAMRebateTable_METTierLineType));
            tierLineType.visible(true);

            FormDataSource rebateDeal_ds=sender;
           
            rebateDeal_ds.object(fieldNum(TAMRebateDeal,RebateOutputType)).enabled(rebateDeal.METVolumetricTierDeal == NoYes::Yes);
            rebateDeal_ds.object(fieldNum(TAMRebateDeal,RebateTypeGUP)).enabled(rebateDeal.METVolumetricTierDeal == NoYes::Yes);
        
            if (rebateDeal.State == TAMRebateDealWorkflowState::Draft)
            {
                tierLineType.enabled(true);
            }
            else
            {
                tierLineType.enabled(false);
            }

           /* FormControl     addLineControl    = sender.formRun().design().controlName(formControlStr(TAMRebateDeal, AddLine));
            addLineControl.enabled(false);
            FormControl     removeLineControl    = sender.formRun().design().controlName(formControlStr(TAMRebateDeal, RemoveLine));
            removeLineControl.enabled(false);*/
        } 
        else
        {
            FormControl tierLineType   = sender.formRun().design().controlName(formControlStr(TAMRebateDeal, TAMRebateTable_METTierLineType));
            tierLineType.visible(false);
            FormDataSource rebateDeal_ds=sender;
           
            rebateDeal_ds.object(fieldNum(TAMRebateDeal,RebateOutputType)).enabled(rebateDeal.METVolumetricTierDeal == NoYes::Yes);
            rebateDeal_ds.object(fieldNum(TAMRebateDeal,RebateTypeGUP)).enabled(rebateDeal.METVolumetricTierDeal == NoYes::Yes);        
        
            //FormControl     addLineControl    = sender.formRun().design().controlName(formControlStr(TAMRebateDeal, AddLine));
            //addLineControl.enabled(false);
            //FormControl     removeLineControl    = sender.formRun().design().controlName(formControlStr(TAMRebateDeal, RemoveLine));
            //removeLineControl.enabled(false);
        }
    }

    /// <summary>
    ///
    /// </summary>
    /// <param name="sender"></param>
    /// <param name="e"></param>
    [FormDataSourceEventHandler(formDataSourceStr(TAMRebateDeal, TAMRebateTable), FormDataSourceEventType::InitValue)]
    public static void TAMRebateTable_OnInitValue(FormDataSource sender, FormDataSourceEventArgs e)
    {
        TAMRebateTable rebateTable = sender.cursor();
            
        TAMRebateDeal rebateDeal = TAMRebateDeal::find(rebateTable.RebateDeal);

        if (rebateDeal.METVolumetricTierDeal == NoYes::Yes)
        {
            if (rebateTable.METTierLineType == METTierLineType::Rate)
            {
                rebateTable.CalculationMethod = TAMRebateCalcMethod::Cumulative;
                rebateTable.RebateBasis = TAMRebateBasis::Value;
                rebateTable.SourceType = TAMRebateSourceType::Invoice;
                rebateTable.UnitId = "";
                rebateTable.MinimumAmount = 0.00;
                rebateTable.Category = 0;
                rebateTable.RebatePostingId = "";
                rebateTable.GuaranteePostingId = "";
                rebateTable.IncludeTax = NoYes::No;
                rebateTable.IncludeCreditNote = NoYes::Yes;
                rebateTable.IncludeDiscountedAmount = NoYes::No;
                rebateTable.PaidInvoices = NoYes::No;
                rebateTable.IncludeFreeText = NoYes::No;
                rebateTable.IncludeSettlementDiscount = NoYes::No;
                rebateTable.SupportNegativeTier = NoYes::No;
                rebateTable.DocumentNotes = "";
            }
            /*else if (rebateTable.METTierLineType == METTierLineType::Rate)
            {
                rebateTable.CalculationMethod = TAMRebateCalcMethod::Cumulative;
                rebateTable.RebateBasis = TAMRebateBasis::Value;
            }*/
        }       
    }

    /// <summary>
    ///
    /// </summary>
    /// <param name="sender"></param>
    /// <param name="e"></param>
    [FormDataSourceEventHandler(formDataSourceStr(TAMRebateDeal, TAMRebateDate), FormDataSourceEventType::InitValue)]
    public static void TAMRebateDate_OnInitValue(FormDataSource sender, FormDataSourceEventArgs e)
    {
        TAMRebateDate rebateDate = sender.cursor();

        TAMRebateTable rebateTable = TAMRebateTable::find(rebateDate.RebateId);
            
        TAMRebateDeal rebateDeal = TAMRebateDeal::find(rebateTable.RebateDeal);

        if (rebateDeal.METVolumetricTierDeal == NoYes::Yes)
        {
            rebateDate.RebateFromDate = rebateDeal.RebateFromDate;
            rebateDate.RebateToDate = rebateDeal.RebateToDate;
            rebateDate.RebatePer = 1;
            rebateDate.RebatePeriodCode = TAMRebatePeriodCode::Week;
            rebateDate.RebateStartingDayOfWeek = WeekDays::Sunday;
            rebateDate.RebateClaimBy = TAMRebatePeriodCode::Period;
            rebateDate.RebateClaimPer = 1;
            rebateDate.METAvgBy454Week = NoYes::Yes;
            rebateDate.ProcessPosting = NoYes::No;             
        }
    }

